// ========== 1. 状态检查 ==========
const root = $json;
const code = root.code;
const msg = root.message || root.msg || '';
const codeStr = String(code);
if (!['0','200'].includes(codeStr)) {
  let tip = '';
  if (codeStr === '401') tip = 'API Key 错误';
  else if (codeStr === '403') tip = '权限不足';
  else if (codeStr === '404') tip = '视频 ID 不存在';
  else if (codeStr === '429') tip = '请求过频或免费额度用完';
  throw new Error('TikHub 错误: ' + code + ' ' + msg + ' \n提示: ' + tip);
}

// ========== 2. 智能定位数据源 ==========
function findDataObj(obj) {
  if (obj.data && obj.data.aweme_detail) return obj.data.aweme_detail;
  if (obj.data && typeof obj.data === 'object') return obj.data;
  return obj;
}
const data = findDataObj(root);

// ========== 3. 安全取值 ==========
function safeGet(obj, path, defaultVal) {
  if (!obj || typeof obj !== 'object') return defaultVal;
  const parts = path.split('.');
  let cur = obj;
  for (let p of parts) {
    if (cur && cur[p] !== undefined && cur[p] !== null) cur = cur[p];
    else return defaultVal;
  }
  return cur;
}

// ========== 4. 提取统计 ==========
const stats = safeGet(data, 'statistics', {}) || {};
const like = Number(stats.digg_count || stats.like_count || stats.diggCount || 0);
const comment = Number(stats.comment_count || stats.commentCount || 0);
const share = Number(stats.share_count || stats.shareCount || 0);
const favorite = Number(stats.collect_count || stats.favorite_count || stats.collectCount || 0);

// ========== 5. 提取作者 ==========
const author = safeGet(data, 'author', {}) || {};
const authorName = author.nickname || author.name || author.unique_id || '';
const authorId = author.unique_id || author.sec_uid || '';

// ========== 6. 基本信息 ==========
const title = safeGet(data, 'desc', '') || safeGet(data, 'title', '');
const duration = Number(safeGet(data, 'duration', 0) || safeGet(data, 'video.duration', 0));
const pubTime = Number(safeGet(data, 'create_time', 0) || safeGet(data, 'publish_time', 0) || safeGet(data, 'ctime', 0));
const pubDate = pubTime ? new Date(pubTime * 1000).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai' }) : '';

// ========== 7. 播放地址 ==========
const videoObj = safeGet(data, 'video', {}) || {};
const playAddr = (videoObj.play_addr && videoObj.play_addr.url_list && videoObj.play_addr.url_list[0]) || videoObj.play_addr || '';
if (!playAddr) {
  throw new Error('没拿到播放地址，逐字稿这一段跑不了。先检查视频 ID 是否正确。');
}

// ========== 8. 平台 ==========
const plat = root.platform || $('配置参数').first().json.platform || 'unknown';
const map = { 'douyin':'抖音', 'tiktok':'TikTok', 'bilibili':'B站', 'xiaohongshu':'小红书', 'kuaishou':'快手', 'weibo':'微博', 'zhihu':'知乎' };
const platformName = map[plat] || plat;

// ========== 9. 输出（12个字段） ==========
return [{
  json: {
    '平台': platformName,
    '数据来源': 'TikHub API',
    '视频标题': title,
    '作者名称': authorName,
    '作者ID': authorId,
    '发布时间': pubDate,
    '时长秒': duration,
    '点赞数': like,
    '评论数': comment,
    '分享数': share,
    '收藏数': favorite,
    '播放地址': playAddr
  }
}];

// 异步任务就像取餐小票：提交后拿到 task_id（小票号），凭小票来问「好了没」
const out = $json.output || {};
const status = out.task_status || '';
if (status === 'FAILED' || status === 'CANCELED' || status === 'UNKNOWN') {
  const detail = JSON.stringify(out).slice(0, 500);
  throw new Error('转写任务失败（' + status + '）。常见原因：① 播放地址过期（重跑一次前面的 TikHub 节点拿新地址）② 百炼 Key 错误或未开通。原始返回: ' + detail);
}
if (status === 'SUCCEEDED') {
  const sub = (out.results && out.results[0]) || {};
  if (sub.subtask_status && sub.subtask_status !== 'SUCCEEDED') {
    throw new Error('转写子任务失败: ' + JSON.stringify(sub).slice(0, 500));
  }
  if (!sub.transcription_url) {
    throw new Error('任务成功但没拿到 transcription_url，原始返回: ' + JSON.stringify(out).slice(0, 500));
  }
}
return [{ json: $json }];

// 把 12 个字段和逐字稿并成一行
const info = $('检查状态并提取数据').first().json;
const trans = $json;
let text = '';
if (trans.transcripts && trans.transcripts[0]) {
  const t = trans.transcripts[0];
  if (t.text) {
    text = t.text;
  } else if (Array.isArray(t.sentences)) {
    text = t.sentences.map(s => s.text).join('');
  }
}
if (!text) {
  throw new Error('逐字稿为空。可能是纯音乐/无人声视频，或结果结构变了。原始返回前500字: ' + JSON.stringify(trans).slice(0, 500));
}
return [{ json: Object.assign({}, info, { '逐字稿': text }) }];
